parameters.jsCode:
const item = $input.first().json;
const body = item.body || item;

let rawPhone = String(body.phone || body.mobile || '').trim();
let cleanPhone = rawPhone.replace(/\D/g, '');
if (cleanPhone.startsWith('05') && cleanPhone.length === 10) {
  cleanPhone = '966' + cleanPhone.slice(1);
}

if (cleanPhone.length < 8) {
  throw new Error('Validation Failed: Invalid phone number ' + rawPhone);
}

const guestName = String(body.full_name || body.name || 'Honored Guest').trim();
const country = String(body.country || 'Global').trim();
const arrivalDate = String(body.arrival_date || '').trim();
const departureDate = String(body.departure_date || '').trim();
const partySummary = String(body.guest_count || body.party_type || '2 Guests').trim();

return [{
  json: {
    cleanPhone,
    chatId: cleanPhone + '@s.whatsapp.net',
    guestName,
    country,
    arrivalDate,
    departureDate,
    partySummary,
    rawPayload: body,
    receivedAt: new Date().toISOString()
  }
}];

